import numpy as np

def triangular(k):
    return k * (k + 1) // 2

def f_cantor(x, y):
    """Cantor pairing function: f(x, y) = T_{x+y} + x"""
    return triangular(x + y) + x

def count_odd_for_cantor(X_limit, Y_limit):
    N = 0
    for x in range(X_limit):
        for y in range(Y_limit):
            if f_cantor(x, y) % 2 != 0:
                N += 1
    return N

# The problem asks for 0 <= x, y < 100
N_cantor = count_odd_for_cantor(100, 100)
print(f"N for Cantor function: {N_cantor}")

import numpy as np

def triangular(k):
    return k * (k + 1) // 2

def f_prime(x, y):
    """Bijection f'(x, y) = T_{x+y} + y"""
    return triangular(x + y) + y

def count_odd_for_f_prime(X_limit, Y_limit):
    N = 0
    for x in range(X_limit):
        for y in range(Y_limit):
            if f_prime(x, y) % 2 != 0:
                N += 1
    return N

# The problem asks for 0 <= x, y < 100
N_prime = count_odd_for_f_prime(100, 100)
print(f"N for f'(x, y) = T_{{x+y}} + y: {N_prime}")
